class Extractor:
    def __init__(self, source):
        self.source = source
        self.rows = []

    def load(self):
        self.rows = read(self.source)
        return len(self.rows)

class CsvExtractor(Extractor):
    def load(self):
        self.rows = parse_csv(self.source)
        return len(self.rows)

    def __repr__(self):
        return f'CsvExtractor({self.source!r})'
